package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

// Kernel selection is deliberately separate from the optional application groups.
// Only repository packages are used; boot files are generated by package hooks.
func kernelChannel(s Settings) string {
	if s.KernelChannel == "" {
		return "unchanged"
	}
	return s.KernelChannel
}

func kernelPackage(s Settings) string {
	switch kernelChannel(s) {
	case "rc":
		return "linux-cachyos-rc"
	case "stable":
		return "linux-cachyos"
	default:
		return ""
	}
}

type kernelEntry struct {
	ID       string   `json:"id"`
	Type     string   `json:"type"`
	Root     string   `json:"root"`
	Linux    string   `json:"linux"`
	Initrd   []string `json:"initrd"`
	Selected bool     `json:"isSelected"`
	Default  bool     `json:"isDefault"`
}

type kernelManager struct {
	c *Context
	// root is / in production; tests use an isolated filesystem.
	root string
	// Tests with user-owned image fixtures supply a reader explicitly. Production
	// always uses the separate root-owned image reader, never the user-file guard.
	imageHash func(string) (string, error)
}

func (k kernelManager) path(path string) string {
	return filepath.Join(k.root, strings.TrimPrefix(path, "/"))
}
func (k kernelManager) query(args ...string) (CommandResult, error) {
	return k.c.Command(Command{Args: args, Env: map[string]string{"LC_ALL": "C", "SYSTEMD_COLORS": "0"}, Timeout: 30 * time.Second})
}
func (k kernelManager) change(args ...string) error {
	_, err := k.c.Command(Command{Args: args, Env: map[string]string{"LC_ALL": "C"}, Interactive: true})
	return err
}

func (k kernelManager) installed() (map[string]string, error) {
	result, err := k.query("pacman", "-Q")
	if err != nil {
		return nil, err
	}
	packages := map[string]string{}
	for _, line := range strings.Split(result.Stdout, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 2 {
			packages[fields[0]] = fields[1]
		}
	}
	if len(packages) == 0 {
		return nil, errors.New("cannot read installed package inventory")
	}
	return packages, nil
}

func (k kernelManager) entries() ([]kernelEntry, error) {
	result, err := k.query("bootctl", "list", "--json=short", "--no-pager")
	if err != nil {
		return nil, err
	}
	var entries []kernelEntry
	if json.Unmarshal([]byte(result.Stdout), &entries) != nil || len(entries) == 0 {
		return nil, errors.New("cannot parse bootctl entries")
	}
	return entries, nil
}

// Reject UKIs and unfamiliar layouts until their signing and image contents can
// be validated. An installed loader alone is not evidence it booted this system.
func (k kernelManager) bootEnvironment() error {
	result, err := k.query("bootctl", "status", "--no-pager")
	if err != nil {
		return fmt.Errorf("cannot verify active bootloader: %w", err)
	}
	current := strings.SplitN(result.Stdout, "Current Boot Loader:", 2)
	if len(current) != 2 {
		return errors.New("unsupported bootloader; use the CachyOS kernel manager and boot menu manually")
	}
	section := strings.SplitN(current[1], "\n\n", 2)[0]
	if !regexp.MustCompile(`(?m)^\s*Product:\s+systemd-boot\b`).MatchString(section) {
		return errors.New("automatic kernel selection requires the active systemd-boot loader; use CachyOS kernel manager for GRUB, Limine or rEFInd")
	}
	if !regexp.MustCompile(`(?m)^\s*Secure Boot:\s+disabled\b`).MatchString(result.Stdout) {
		return errors.New("Secure Boot is enabled or unknown; configure and validate signed kernels manually")
	}
	return nil
}

func (k kernelManager) regularFile(path string) error {
	info, err := os.Lstat(k.path(path))
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() || info.Size() == 0 {
		return fmt.Errorf("missing, empty or non-regular boot file: %s", path)
	}
	return nil
}

func entryFor(entries []kernelEntry, pkg string) (kernelEntry, error) {
	var matches []kernelEntry
	for _, entry := range entries {
		if entry.Type == "type1" && filepath.Base(entry.Linux) == "vmlinuz-"+pkg {
			for _, initrd := range entry.Initrd {
				if filepath.Base(initrd) == "initramfs-"+pkg+".img" {
					matches = append(matches, entry)
					break
				}
			}
		}
	}
	if len(matches) != 1 {
		return kernelEntry{}, fmt.Errorf("need exactly one standard systemd-boot entry for %s; found %d (UKIs/custom layouts need manual validation)", pkg, len(matches))
	}
	entry := matches[0]
	if !regexp.MustCompile(`^[A-Za-z0-9_.+-]+\.conf$`).MatchString(entry.ID) {
		return kernelEntry{}, errors.New("unsafe or unsupported boot entry ID")
	}
	return entry, nil
}

func (k kernelManager) validateEntry(entry kernelEntry) error {
	if !contains([]string{"/boot", "/efi", "/boot/efi"}, entry.Root) {
		return fmt.Errorf("unsupported boot partition: %s", entry.Root)
	}
	for _, path := range append([]string{entry.Linux}, entry.Initrd...) {
		if !strings.HasPrefix(path, "/") || filepath.Clean(path) != path {
			return fmt.Errorf("invalid boot image path: %s", path)
		}
		if err := k.regularFile(filepath.Join(entry.Root, path)); err != nil {
			return err
		}
	}
	for _, path := range entry.Initrd {
		if strings.HasPrefix(filepath.Base(path), "initramfs-") {
			if _, err := k.query("lsinitcpio", "-l", filepath.Join(entry.Root, path)); err != nil {
				return fmt.Errorf("invalid initramfs: %w", err)
			}
		}
	}
	return nil
}

func (k kernelManager) checkSpace(root string) error {
	// findmnt --mountpoint rejects an unmounted ESP directory. Require both the
	// boot partition and /boot when separate: package hooks may write to either.
	for _, path := range uniqueStrings([]string{root, "/boot"}) {
		result, err := k.query("findmnt", "--noheadings", "--output", "OPTIONS", "--target", path)
		if err != nil || !contains(strings.Split(strings.TrimSpace(result.Stdout), ","), "rw") {
			return fmt.Errorf("%s is not on a verified writable filesystem", path)
		}
		if path == root {
			if _, err = k.query("findmnt", "--mountpoint", path, "--noheadings"); err != nil {
				return fmt.Errorf("boot partition %s is not mounted", path)
			}
		}
		result, err = k.query("df", "-B1", "--output=avail", path)
		if err != nil {
			return err
		}
		fields := strings.Fields(result.Stdout)
		if len(fields) != 2 {
			return fmt.Errorf("cannot determine free space on %s", path)
		}
		available, err := strconv.ParseUint(fields[1], 10, 64)
		if err != nil || available < 1024*1024*1024 {
			return fmt.Errorf("need at least 1 GiB free on %s for kernel images and fallback", path)
		}
	}
	return nil
}

func uniqueStrings(values []string) []string {
	result := []string{}
	for _, value := range values {
		if !contains(result, value) {
			result = append(result, value)
		}
	}
	return result
}

func (k kernelManager) fallback(packages map[string]string, entries []kernelEntry, target string) (string, kernelEntry, error) {
	for _, pkg := range []string{"linux-cachyos-lts", "linux-lts", "linux-cachyos", "linux"} {
		if pkg == target || packages[pkg] == "" {
			continue
		}
		entry, err := entryFor(entries, pkg)
		if err == nil && k.validateEntry(entry) == nil {
			return pkg, entry, nil
		}
	}
	return "", kernelEntry{}, errors.New("no validated stable/LTS fallback distinct from the selected kernel; install and boot a separate stable or LTS kernel with a standard boot entry first")
}

// Prebuilt drivers must follow the installed driver family. DKMS is blocked
// because a successful dependency solve cannot establish RC build compatibility.
func kernelModuleSuffixes(packages map[string]string) ([]string, error) {
	modules := []string{}
	for pkg := range packages {
		if strings.HasPrefix(pkg, "virtualbox-host-modules") || strings.HasPrefix(pkg, "vmware") {
			return nil, fmt.Errorf("out-of-tree module provider %s requires manual kernel compatibility validation", pkg)
		}
		if strings.HasPrefix(pkg, "linux-") {
			for _, suffix := range []string{"r8125", "r8168", "acpi_call", "v4l2loopback"} {
				if strings.HasSuffix(pkg, "-"+suffix) {
					return nil, fmt.Errorf("prebuilt module %s requires manual compatibility validation", pkg)
				}
			}
		}
		if strings.Contains(pkg, "nvidia") && !contains([]string{"nvidia-utils", "lib32-nvidia-utils", "nvidia-settings", "opencl-nvidia", "lib32-opencl-nvidia", "nvidia", "nvidia-open"}, pkg) && !strings.HasSuffix(pkg, "-nvidia") && !strings.HasSuffix(pkg, "-nvidia-open") && !strings.HasSuffix(pkg, "-headers") {
			return nil, fmt.Errorf("unverified NVIDIA package %s; validate its kernel provider manually", pkg)
		}
		if strings.Contains(pkg, "-dkms") {
			return nil, fmt.Errorf("%s requires manual RC build/boot validation; automatic DKMS activation is unsupported", pkg)
		}
		if (strings.HasPrefix(pkg, "linux-") && strings.HasSuffix(pkg, "-nvidia-open")) || pkg == "nvidia-open" {
			modules = append(modules, "nvidia-open")
		}
		if (strings.HasPrefix(pkg, "linux-") && strings.HasSuffix(pkg, "-nvidia")) || pkg == "nvidia" {
			modules = append(modules, "nvidia")
		}
		if strings.HasSuffix(pkg, "-zfs") || pkg == "zfs-linux" {
			modules = append(modules, "zfs")
		}
	}
	modules = uniqueStrings(modules)
	if contains(modules, "nvidia") && contains(modules, "nvidia-open") {
		return nil, errors.New("ambiguous NVIDIA driver families; resolve manually")
	}
	if packages["nvidia-utils"] != "" && !contains(modules, "nvidia") && !contains(modules, "nvidia-open") {
		return nil, errors.New("cannot establish NVIDIA kernel module provider")
	}
	if packages["zfs-utils"] != "" && !contains(modules, "zfs") {
		return nil, errors.New("cannot establish ZFS kernel module provider")
	}
	sort.Strings(modules)
	return modules, nil
}

func (k kernelManager) requiredModules(packages map[string]string) ([]string, error) {
	suffixes, err := kernelModuleSuffixes(packages)
	if err != nil {
		return nil, err
	}
	if packages["dkms"] != "" {
		status, err := k.query("dkms", "status")
		if err != nil || strings.TrimSpace(status.Stdout) != "" {
			return nil, errors.New("registered DKMS modules require manual kernel compatibility validation")
		}
	}
	return suffixes, nil
}

type kernelCandidate struct {
	Name       string `json:"name"`
	Repository string `json:"repository"`
	Version    string `json:"version"`
}

func (k kernelManager) candidate(name string, installed map[string]string) (kernelCandidate, error) {
	result, err := k.query("pacman", "-Si", "--color", "never", "--", name)
	if err != nil {
		return kernelCandidate{}, fmt.Errorf("required repository kernel package %s unavailable: %w", name, err)
	}
	fields := map[string]string{}
	for _, line := range strings.Split(result.Stdout, "\n") {
		key, value, ok := strings.Cut(line, ":")
		if ok {
			fields[strings.TrimSpace(key)] = strings.TrimSpace(value)
		}
	}
	candidate := kernelCandidate{name, fields["Repository"], fields["Version"]}
	if fields["Name"] != name || candidate.Version == "" || !contains([]string{"cachyos", "cachyos-v3", "cachyos-v4", "cachyos-znver4"}, candidate.Repository) {
		return candidate, fmt.Errorf("%s is not an exact package from a supported CachyOS repository", name)
	}
	if installed[name] != "" {
		compare, err := k.query("vercmp", candidate.Version, installed[name])
		if err != nil {
			return candidate, err
		}
		n, err := strconv.Atoi(strings.TrimSpace(compare.Stdout))
		if err != nil || n < 0 {
			return candidate, fmt.Errorf("refusing downgrade or unknown version ordering for %s (%s -> %s)", name, installed[name], candidate.Version)
		}
	}
	return candidate, nil
}

func (k kernelManager) moduleRelease(pkg string) (string, error) {
	result, err := k.query("pacman", "-Ql", "--", pkg)
	if err != nil {
		return "", err
	}
	releases := []string{}
	for _, line := range strings.Split(result.Stdout, "\n") {
		fields := strings.Fields(line)
		if len(fields) != 2 || fields[0] != pkg {
			continue
		}
		path := fields[1]
		if strings.HasPrefix(path, "/usr/lib/modules/") && strings.HasSuffix(path, "/vmlinuz") {
			release := strings.TrimSuffix(strings.TrimPrefix(path, "/usr/lib/modules/"), "/vmlinuz")
			if !strings.Contains(release, "/") && release != "" {
				releases = append(releases, release)
			}
		}
	}
	if len(releases) != 1 {
		return "", fmt.Errorf("cannot identify installed kernel release for %s", pkg)
	}
	return releases[0], nil
}

func (k kernelManager) validateModules(pkg string, suffixes []string) (string, error) {
	release, err := k.moduleRelease(pkg)
	if err != nil {
		return "", err
	}
	for _, suffix := range suffixes {
		modules := []string{suffix}
		if strings.HasPrefix(suffix, "nvidia") {
			modules = []string{"nvidia", "nvidia_modeset", "nvidia_drm", "nvidia_uvm"}
		}
		for _, module := range modules {
			result, err := k.query("modinfo", "-k", release, "-F", "vermagic", module)
			fields := strings.Fields(result.Stdout)
			if err != nil || len(fields) == 0 || fields[0] != release {
				return "", fmt.Errorf("%s is missing or incompatible with %s", module, release)
			}
		}
	}
	return release, nil
}

// Validate both the package's image and the generated initramfs. Pacman can
// finish with a post-transaction hook error, so exit status alone is insufficient.
func (k kernelManager) verifyKernel(pkg string, entry kernelEntry, suffixes []string) (string, error) {
	if err := k.validateEntry(entry); err != nil {
		return "", err
	}
	release, err := k.validateModules(pkg, suffixes)
	if err != nil {
		return "", err
	}
	packaged := k.path("/usr/lib/modules/" + release + "/vmlinuz")
	boot := k.path(filepath.Join(entry.Root, entry.Linux))
	hashImage := k.imageHash
	if hashImage == nil {
		hashImage = trustedKernelImageHash
	}
	packagedHash, err := hashImage(packaged)
	if err != nil {
		return "", err
	}
	bootHash, err := hashImage(boot)
	if err != nil || bootHash != packagedHash {
		return "", fmt.Errorf("boot image for %s does not match installed kernel; repair package hooks before reboot", pkg)
	}
	for _, path := range entry.Initrd {
		if filepath.Base(path) != "initramfs-"+pkg+".img" {
			continue
		}
		listing, err := k.query("lsinitcpio", "-l", filepath.Join(entry.Root, path))
		if err != nil || !strings.Contains(listing.Stdout, "lib/modules/"+release+"/") {
			return "", fmt.Errorf("initramfs for %s does not contain modules for %s", pkg, release)
		}
	}
	return release, nil
}

func UpgradeKernel(c *Context) error { return (kernelManager{c: c, root: "/"}).upgrade() }
func (k kernelManager) upgrade() error {
	if k.c.CheckOnly || k.c.Options.DryRun || k.c.Options.Check {
		return errors.New("kernel changes are unavailable in read-only mode")
	}
	target := kernelPackage(k.c.Settings)
	if target == "" {
		return errors.New("select stable or rc kernel_channel first")
	}
	if err := k.bootEnvironment(); err != nil {
		return err
	}
	installed, err := k.installed()
	if err != nil {
		return err
	}
	suffixes, err := k.requiredModules(installed)
	if err != nil {
		return err
	}
	entries, err := k.entries()
	if err != nil {
		return err
	}
	fallback, entry, err := k.fallback(installed, entries, target)
	if err != nil {
		return err
	}
	if err = k.checkSpace(entry.Root); err != nil {
		return err
	}
	if _, err = k.verifyKernel(fallback, entry, suffixes); err != nil {
		return fmt.Errorf("fallback: %w", err)
	}
	record := map[string]any{"channel": kernelChannel(k.c.Settings), "target": target, "fallback": fallback, "fallback_entry": entry.ID, "status": "preflight_passed"}
	k.c.Report["kernel"] = record
	k.c.Note("Kernel channel " + kernelChannel(k.c.Settings) + ": retain " + fallback + " as the default until an explicit trial boot and promotion.")
	// Sync and download a full upgrade without installing anything. Resolution
	// below uses the refreshed databases; the install then uses -Su, never -Sy.
	k.c.Warn("If kernel resolution fails after database refresh, complete a full pacman -Syu before installing other packages.")
	if err = k.change("sudo", "pacman", "-Syu", "--downloadonly"); err != nil {
		return err
	}
	names := []string{target, target + "-headers"}
	for _, suffix := range suffixes {
		names = append(names, target+"-"+suffix)
	}
	candidates := []kernelCandidate{}
	targets := []string{"base-devel", "git", fallback}
	for _, name := range names {
		candidate, err := k.candidate(name, installed)
		if err != nil {
			return err
		}
		candidates = append(candidates, candidate)
		targets = append(targets, candidate.Repository+"/"+name)
	}
	if candidates[0].Version != candidates[1].Version {
		return errors.New("kernel and headers repository versions do not match")
	}
	record["resolved_packages"] = candidates
	if err = k.c.Save(); err != nil {
		return err
	}
	// Ask pacman to resolve and download the exact selected package transaction
	// before changing any boot selection. Its solver checks prebuilt driver dependencies.
	if err = k.change(append([]string{"sudo", "pacman", "-Su", "--downloadonly", "--needed", "--"}, uniqueStrings(targets)...)...); err != nil {
		return err
	}
	// Pin a known fallback before hooks can introduce a newer sorted entry.
	if err = k.change("sudo", "bootctl", "set-default", entry.ID); err != nil {
		return err
	}
	if err = k.change("sudo", "bootctl", "set-oneshot", ""); err != nil {
		return err
	}
	if err = k.change(append([]string{"sudo", "pacman", "-Su", "--needed", "--"}, uniqueStrings(targets)...)...); err != nil {
		return fmt.Errorf("kernel transaction failed; do not reboot before checking fallback images: %w", err)
	}
	installed, err = k.installed()
	if err != nil {
		return err
	}
	for _, candidate := range candidates {
		if installed[candidate.Name] != candidate.Version {
			return fmt.Errorf("%s was not installed at resolved version %s", candidate.Name, candidate.Version)
		}
	}
	if installed[fallback] == "" {
		return errors.New("fallback package disappeared; repair it before reboot")
	}
	entries, err = k.entries()
	if err != nil {
		return err
	}
	for _, pkg := range uniqueStrings([]string{fallback, target}) {
		verified, err := entryFor(entries, pkg)
		if err != nil {
			return err
		}
		if pkg == fallback && (verified.ID != entry.ID || !verified.Default) {
			return errors.New("fallback boot entry or default changed during upgrade; repair before reboot")
		}
		release, err := k.verifyKernel(pkg, verified, suffixes)
		if err != nil {
			return err
		}
		if pkg == target {
			record["installed_release"] = release
			record["entry"] = verified.ID
		}
	}
	record["status"] = "installed_not_activated"
	if running, err := k.query("uname", "-r"); err == nil {
		record["running"] = strings.TrimSpace(running.Stdout)
		record["reboot_required"] = record["running"] != record["installed_release"]
	}
	k.c.Note("Kernel images and fallback validated. Use --kernel-boot once for a trial; reboot manually. After testing the new session, use --kernel-boot promote.")
	return k.c.Save()
}

func CheckKernel(c *Context) error { return (kernelManager{c: c, root: "/"}).check() }

func (k kernelManager) check() error {
	c := k.c
	record := map[string]any{"channel": kernelChannel(c.Settings), "repository_versions": "cached; provisional until apply refreshes databases"}
	c.Report["kernel"] = record
	running, err := k.query("uname", "-r")
	if err != nil {
		return err
	}
	record["running"] = strings.TrimSpace(running.Stdout)
	installed, err := k.installed()
	if err != nil {
		return err
	}
	kernels := map[string]string{}
	for _, pkg := range []string{"linux-cachyos-rc", "linux-cachyos", "linux-cachyos-lts", "linux", "linux-lts"} {
		if installed[pkg] != "" {
			kernels[pkg] = installed[pkg]
		}
	}
	record["installed"] = kernels
	target := kernelPackage(c.Settings)
	if target == "" {
		return nil
	}
	if err := k.bootEnvironment(); err != nil {
		return err
	}
	record["target"] = target
	if installed[target] == "" {
		return fmt.Errorf("selected kernel %s is not installed", target)
	}
	release, err := k.moduleRelease(target)
	if err != nil {
		return err
	}
	record["installed_release"] = release
	record["installed_version"] = installed[target]
	record["reboot_required"] = release != record["running"]
	if candidate, err := k.candidate(target, installed); err == nil {
		record["cached_available_version"] = candidate.Version
	} else {
		record["repository_error"] = err.Error()
	}
	entries, err := k.entries()
	if err != nil {
		return err
	}
	fallback, entry, err := k.fallback(installed, entries, target)
	if err != nil {
		return err
	}
	record["fallback"] = fallback
	record["fallback_entry"] = entry.ID
	targetEntry, err := entryFor(entries, target)
	if err != nil {
		return err
	}
	suffixes, err := k.requiredModules(installed)
	if err != nil {
		return err
	}
	if _, err = k.verifyKernel(target, targetEntry, suffixes); err != nil {
		return err
	}
	if _, err = k.verifyKernel(fallback, entry, suffixes); err != nil {
		return err
	}
	record["entry"] = targetEntry.ID
	record["default"] = targetEntry.Default
	return nil
}

func KernelBoot(c *Context, action string) error {
	return (kernelManager{c: c, root: "/"}).boot(action)
}
func (k kernelManager) boot(action string) error {
	if k.c.CheckOnly || k.c.Options.DryRun || k.c.Options.Check {
		return errors.New("boot selection is unavailable in read-only mode")
	}
	if action != "once" && action != "promote" {
		return errors.New("kernel boot action must be once or promote")
	}
	target := kernelPackage(k.c.Settings)
	if target == "" {
		return errors.New("select stable or rc kernel_channel in settings first")
	}
	if err := k.bootEnvironment(); err != nil {
		return err
	}
	packages, err := k.installed()
	if err != nil {
		return err
	}
	if packages[target] == "" || packages[target] != packages[target+"-headers"] {
		return errors.New("matching selected kernel and headers are not installed")
	}
	suffixes, err := k.requiredModules(packages)
	if err != nil {
		return err
	}
	entries, err := k.entries()
	if err != nil {
		return err
	}
	fallback, fallbackEntry, err := k.fallback(packages, entries, target)
	if err != nil {
		return err
	}
	if _, err = k.verifyKernel(fallback, fallbackEntry, suffixes); err != nil {
		return err
	}
	entry, err := entryFor(entries, target)
	if err != nil {
		return err
	}
	release, err := k.verifyKernel(target, entry, suffixes)
	if err != nil {
		return err
	}
	if action == "promote" {
		running, err := k.query("uname", "-r")
		if err != nil {
			return err
		}
		if !entry.Selected || strings.TrimSpace(running.Stdout) != release {
			return errors.New("promotion requires booting the currently installed selected kernel first")
		}
		if err = k.change("sudo", "bootctl", "set-default", entry.ID); err != nil {
			return err
		}
		k.c.Note("Selected kernel is now the default. Keep the stable/LTS fallback installed.")
	} else {
		if err = k.change("sudo", "bootctl", "set-default", fallbackEntry.ID); err != nil {
			return err
		}
		if err = k.change("sudo", "bootctl", "set-oneshot", entry.ID); err != nil {
			return err
		}
		k.c.Note("One-time kernel boot selected; the stable/LTS entry remains the default. Save work and reboot manually. Test graphics, networking and suspend before promotion.")
	}
	return nil
}

// A preview uses local package databases only; it does not refresh mirrors,
// create reports, request sudo, or validate a boot that has not happened yet.
func kernelPlanObservation(c *Context) string {
	k := kernelManager{c: c, root: "/"}
	v := &planView{}
	v.section("Local kernel inventory")
	if running, err := k.query("uname", "-r"); err == nil {
		v.field("Running", strings.TrimSpace(running.Stdout))
	}
	installed, err := k.installed()
	if err != nil {
		v.note("Installed kernels unavailable: " + err.Error())
		return v.String()
	}
	for _, pkg := range []string{"linux-cachyos-rc", "linux-cachyos", "linux-cachyos-lts", "linux", "linux-lts"} {
		if version := installed[pkg]; version != "" {
			v.field(pkg, version)
		}
	}
	target := kernelPackage(c.Settings)
	if candidate, err := k.candidate(target, installed); err == nil {
		v.field("Cached candidate", candidate.Version)
	} else {
		v.note("Cached candidate unresolved: " + err.Error())
	}
	if installed[target] != "" {
		if release, err := k.moduleRelease(target); err == nil {
			v.field("Installed release", release)
			v.note("Compare this with the running release; a different release requires a manual reboot.")
		}
	}
	v.note("Cached versions are provisional. Fallback bootability and module compatibility are checked during apply; no network requests were made.")
	return v.String()
}
